urlset:

    {{ site_url }}/
    {{ lastmod }}
    daily
    1.0


    {{ site_url }}/projects
    {{ lastmod }}
    weekly
    0.8


    {{ site_url }}/articles
    {{ lastmod }}
    daily
    0.8

{%- for project in projects %}

    {{ site_url }}{{ project.url }}
    monthly
    0.6

{%- endfor %}
{%- for article in articles %}

    {{ site_url }}{{ article.url }}
    {{ (article.updated or article.date).isoformat() }}
    monthly
    0.7

{%- endfor %}
